#!/usr/bin/env node
'use strict';

const fs=require('node:fs');
const path=require('node:path');
const {spawnSync}=require('node:child_process');

const root=path.resolve(__dirname,'..');
const payload={
  "admin/admin.js": "",
  "admin/index.html": "",
  "functions/api/admin/translate.js": "",
  "scripts/stage-12.14.4-translation-integrity-test.js": "",
  "scripts/stage-12.14.5-german-translation-adaptation-test.js": ""
};
const adminPath=path.join(root,'admin','admin.js');

if(!fs.existsSync(adminPath))throw new Error('Запустите установщик из папки website: node scripts/install-stage-12.14.5-german-translation-adaptation.js');
const currentAdmin=fs.readFileSync(adminPath,'utf8');
if(!currentAdmin.includes('Stage 12.14.4: detect reasoning/analysis')&&!currentAdmin.includes('function looksEnglishInsteadOfGerman')){
  throw new Error('Сначала требуется установленный Stage 12.14.4. Файлы не изменены.');
}

const packagePath=path.join(root,'package.json');
if(!fs.existsSync(packagePath))throw new Error('package.json не найден. Файлы не изменены.');
const pkg=JSON.parse(fs.readFileSync(packagePath,'utf8'));
pkg.scripts||={};
pkg.scripts['admingerman:test']='node scripts/stage-12.14.5-german-translation-adaptation-test.js';
if(typeof pkg.scripts.test!=='string')throw new Error('package scripts.test отсутствует. Файлы не изменены.');
if(!pkg.scripts.test.includes('admingerman:test'))pkg.scripts.test+=' && npm run admingerman:test';

const writes=new Map(Object.entries(payload).map(([relative,encoded])=>[
  path.join(root,...relative.split('/')),
  Buffer.from(encoded,'base64')
]));
writes.set(packagePath,Buffer.from(JSON.stringify(pkg,null,2)+'\n','utf8'));

const rollback=new Map();
for(const target of writes.keys())rollback.set(target,fs.existsSync(target)?fs.readFileSync(target):null);

try{
  for(const [target,content] of writes){
    fs.mkdirSync(path.dirname(target),{recursive:true});
    fs.writeFileSync(target,content);
  }

  const tests=[
    'scripts/stage-12.14-admin-editor-reliability-test.js',
    'scripts/stage-12.14.2-incremental-admin-editor-test.js',
    'scripts/stage-12.14.3-independent-admin-persistence-test.js',
    'scripts/stage-12.14.4-translation-integrity-test.js',
    'scripts/stage-12.14.5-german-translation-adaptation-test.js'
  ];
  for(const relative of tests){
    const result=spawnSync(process.execPath,[path.join(root,...relative.split('/'))],{cwd:root,encoding:'utf8'});
    if(result.status!==0)throw new Error(`${relative} failed\n${result.stderr||result.stdout}`);
  }
}catch(error){
  for(const [target,content] of rollback){
    if(content===null){
      try{fs.unlinkSync(target);}catch(unlinkError){}
    }else fs.writeFileSync(target,content);
  }
  throw error;
}

console.log('PASS: Stage 12.14.5 German Translation Adaptation installed.');
console.log('PASS: English text can no longer be accepted as a German translation.');
console.log('PASS: German repair uses the existing English line only as a rejection reference.');
console.log('PASS: RU, UA, GE and EN translation behavior is unchanged.');
console.log('PASS: Admin save/draft/publish/media compatibility tests passed.');
console.log('D1 migration: not required.');

